if (HipsMgr.getFlagShow()) {
    core.debug("HiPS surveys are visible");
} else {
    HipsMgr.setFlagShow(true);
}

// Enable HiPS surveys
HipsMgr.setFlagShow(true);

// Disable HiPS surveys
HipsMgr.setFlagShow(false);

// Force reload of HiPS survey sources
HipsMgr.loadSources();
core.debug("HiPS survey sources reloaded");

if (HipsMgr.getFlagShowAtmosphericExtinction()) {
    core.debug("HiPS images fade near the horizon");
}

// Realistic view: fade HiPS images near the horizon
HipsMgr.setFlagShowAtmosphericExtinction(true);

// Uniform brightness for the entire sky
HipsMgr.setFlagShowAtmosphericExtinction(false);
